import{_ as a,o as t,c as s,a2 as n}from"./chunks/framework.D8Tso2Ul.js";const m=JSON.parse('{"title":"Módulo: Asistente IA","description":"","frontmatter":{},"headers":[],"relativePath":"modulos/asistente-ia.md","filePath":"modulos/asistente-ia.md"}'),i={name:"modulos/asistente-ia.md"};function o(d,e,r,l,c,p){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="modulo-asistente-ia" tabindex="-1">Módulo: Asistente IA <a class="header-anchor" href="#modulo-asistente-ia" aria-label="Permalink to &quot;Módulo: Asistente IA&quot;">​</a></h1><p><strong>Ubicación:</strong> <code>Frontend/src/pages/AIAssistant.tsx</code> · <code>Backend/handlers/ai-assistant/</code> · <code>lib/ai/</code></p><p>Chatbot inteligente para consultas de seguridad y generación asistida de matrices de riesgo, con contexto de la normativa chilena.</p><h2 id="modelo-y-proveedores" tabindex="-1">Modelo y proveedores <a class="header-anchor" href="#modelo-y-proveedores" aria-label="Permalink to &quot;Modelo y proveedores&quot;">​</a></h2><ul><li><strong>Modelo principal:</strong> Claude 3 Sonnet (Anthropic) vía <strong>AWS Bedrock</strong>.</li><li><strong>Proveedor alternativo:</strong> Google Gemini API.</li><li>Contexto especializado en seguridad laboral chilena y DS 44.</li></ul><h2 id="capacidades" tabindex="-1">Capacidades <a class="header-anchor" href="#capacidades" aria-label="Permalink to &quot;Capacidades&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capacidad</th><th>Descripción</th></tr></thead><tbody><tr><td>Generación de MIPER / MIPPER</td><td>Propone peligros, riesgos y medidas de control por cargo</td></tr><tr><td>Consultas normativas</td><td>Responde sobre el DS 44 y normativa SST vigente</td></tr><tr><td>Procedimientos de emergencia</td><td>Orientación ante situaciones críticas</td></tr><tr><td>Recomendaciones de EPP</td><td>Sugiere EPP según el cargo y sus riesgos</td></tr><tr><td>Análisis de riesgos</td><td>Apoyo en la identificación y evaluación de peligros</td></tr></tbody></table><h2 id="generacion-de-matrices-de-riesgo" tabindex="-1">Generación de matrices de riesgo <a class="header-anchor" href="#generacion-de-matrices-de-riesgo" aria-label="Permalink to &quot;Generación de matrices de riesgo&quot;">​</a></h2><p>El caso de uso estrella es la <strong>generación asistida de la MIPPER</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. El prevencionista indica el cargo y la actividad</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>2. El asistente propone peligros, riesgos y medidas de control</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>3. El prevencionista revisa, ajusta y completa la matriz</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>4. La MIPPER se guarda como documento DS 44 y se firma</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">El humano siempre valida</p><p>La IA <strong>propone</strong>, pero la responsabilidad técnica y legal recae en el prevencionista, que revisa, corrige y firma la matriz final. La generación asistida acelera el trabajo, no lo reemplaza.</p></div><h2 id="disponibilidad-por-plan" tabindex="-1">Disponibilidad por plan <a class="header-anchor" href="#disponibilidad-por-plan" aria-label="Permalink to &quot;Disponibilidad por plan&quot;">​</a></h2><p>El Asistente IA puede estar habilitado o no según <code>tenant.settings.modulosActivos</code>. Es habitual que se ofrezca en planes <em>professional</em> y <em>enterprise</em>. Ver <a href="/manual/modulos/tenants.html">Tenants</a>.</p><h2 id="endpoints-relacionados" tabindex="-1">Endpoints relacionados <a class="header-anchor" href="#endpoints-relacionados" aria-label="Permalink to &quot;Endpoints relacionados&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Método</th><th>Ruta</th><th>Acción</th></tr></thead><tbody><tr><td><code>POST</code></td><td><code>/ai-assistant/chat</code></td><td>Enviar mensaje al asistente</td></tr></tbody></table>`,15)])])}const u=a(i,[["render",o]]);export{m as __pageData,u as default};
